// Frida OCR Auto-Inject v3 — Proxy Listener
// Uses java.lang.reflect.Proxy to create a dynamic NodeListener

Java.perform(function () {
    console.log("[V3] === OCR Auto-Inject v3 (Proxy Listener) ===");

    var TextInputCallback = Java.use("org.forgerock.android.auth.callback.TextInputCallback");
    var ChoiceCallback = Java.use("org.forgerock.android.auth.callback.ChoiceCallback");

    var B64_IMAGE = "";

    var injected = false;

    // Poll for OCR Node
    var pollCount = 0;
    var pollInterval = setInterval(function () {
        pollCount++;
        if (injected) { clearInterval(pollInterval); return; }

        Java.perform(function () {
            Java.choose("org.forgerock.android.auth.Node", {
                onMatch: function (node) {
                    if (injected) return;
                    try {
                        if (node.getStage() !== "OCR") return;
                        injected = true;
                        clearInterval(pollInterval);
                        console.log("[V3] *** OCR NODE FOUND ***");

                        var context = Java.use("android.app.ActivityThread").currentApplication().getApplicationContext();

                        // Fill callbacks
                        var callbacks = node.getCallbacks();
                        var cb0 = callbacks.get(0);
                        var cb1 = callbacks.get(1);
                        Java.cast(cb0, ChoiceCallback).setSelectedIndex(0);
                        Java.cast(cb1, TextInputCallback).setValue(B64_IMAGE);
                        console.log("[V3] Callbacks filled");

                        // Create proxy listener using java.lang.reflect.Proxy
                        var listener = null;
                        try {
                            var Proxy = Java.use("java.lang.reflect.Proxy");
                            var InvocationHandler = Java.use("java.lang.reflect.InvocationHandler");

                            var HandlerClass = Java.registerClass({
                                name: "com.frida.NodeListenerHandler",
                                implements: [InvocationHandler],
                                methods: {
                                    invoke: function (proxy, method, args) {
                                        var mname = method.getName();
                                        console.log("[PROXY] invoked: " + mname);
                                        if (mname === "onCallbackReceived" && args && args.length > 0) {
                                            console.log("[PROXY] *** CALLBACK RECEIVED! ***");
                                            try {
                                                var newNode = args[0];

                                                // Post to main thread for UI update
                                                var Handler = Java.use("android.os.Handler");
                                                var Looper = Java.use("android.os.Looper");
                                                var mainHandler = Handler.$new(Looper.getMainLooper());

                                                var MainRunnable = Java.registerClass({
                                                    name: "com.frida.HCR" + Date.now(),
                                                    implements: [Java.use("java.lang.Runnable")],
                                                    methods: {
                                                        run: function () {
                                                            console.log("[MAIN] Running on main thread");
                                                            Java.perform(function () {
                                                                // Re-find the NTB_LC node (fresh reference)
                                                                var FRB = Java.use("com.bangkokbank.blue.ping.FRAuthBridge");
                                                                Java.choose("org.forgerock.android.auth.Node", {
                                                                    onMatch: function (n) {
                                                                        try {
                                                                            var st = n.getStage();
                                                                            if (st !== "OCR") {
                                                                                console.log("[MAIN] Found node stage: " + st);
                                                                                // Forward to bridge
                                                                                Java.choose("com.bangkokbank.blue.ping.FRAuthBridge", {
                                                                                    onMatch: function (bridge) {
                                                                                        try {
                                                                                            var cb = Java.cast(bridge, FRB);
                                                                                            cb.handleCallback(n);
                                                                                            console.log("[MAIN] *** handleCallback DONE ***");
                                                                                        } catch (e) {
                                                                                            console.log("[MAIN] handleCallback err: " + e);
                                                                                        }
                                                                                    },
                                                                                    onComplete: function () {}
                                                                                });
                                                                            }
                                                                        } catch (e) {}
                                                                    },
                                                                    onComplete: function () { console.log("[MAIN] node search done"); }
                                                                });
                                                            });
                                                        }
                                                    }
                                                });

                                                mainHandler.post(MainRunnable.$new());
                                                console.log("[PROXY] Posted to main thread");

                                            } catch (e) { console.log("[PROXY] error: " + e); }
                                        }
                                        if (mname === "onException" && args && args.length > 0) {
                                            console.log("[PROXY] Exception: " + args[0]);
                                        }
                                        return null;
                                    }
                                }
                            });
                            var handler = HandlerClass.$new();

                            var NodeListenerClass = Java.use("org.forgerock.android.auth.NodeListener").class;
                            var classArray = Java.array("java.lang.Class", [NodeListenerClass]);
                            // Use app's classloader (not system) so ForgeRock interface is visible
                            var classLoader = Java.use("org.forgerock.android.auth.Node").class.getClassLoader();

                            listener = Proxy.newProxyInstance(classLoader, classArray, handler);
                            console.log("[V3] Proxy listener created: " + listener);
                        } catch (e) {
                            console.log("[V3] Proxy creation failed: " + e);
                        }

                        // Submit
                        console.log("[V3] *** CALLING Node.next() ***");
                        try {
                            node.next(context, listener);
                            console.log("[V3] *** Node.next() COMPLETED ***");
                        } catch (e) {
                            console.log("[V3] Node.next error: " + e);
                        }

                    } catch (e) { console.log("[V3] Error: " + e); }
                },
                onComplete: function () {}
            });
        });

        if (pollCount > 36) { clearInterval(pollInterval); console.log("[V3] Timeout"); }
    }, 5000);

    console.log("[V3] Polling started");
});
